// v16.xx, from the whole-game bug hunt of 2026-10-08 (V-A1): IS A WINDOW OPEN OVER THE FLOOR. Any window that is on counts, except
// the tuning and sim consoles, which openModal lets sit over whatever they tune.
function hubWinOn(){
  var m=document.querySelectorAll('.modal.on'), i;
  for(i=0;i<m.length;i++) if(m[i].id!=='tunemodal'&&m[i].id!=='simmodal') return true;
  return false;
}
function drawHubHUD(ox,oy){

// v16.xx, from the whole-game bug hunt of 2026-10-08 (V-A1): THE FLOOR HEADING STAYS OUT OF A STATION WINDOW. A window is a
// slightly see-through sheet with its frame 14 pixels in from the screen edge, and the floor kept painting this heading in the
// corner behind it, so on the 4K screenshots the top half of THE UNDERCROFT showed above the frame line of the shop, Fashion and
// the other windows, cut in half by it. It is not painted while a window is open and is back the frame it closes. The money
// line under it sits behind the frame and is left as it was.
if(!hubWinOn()) ctx.fillText('THE UNDERCROFT',16,28);

check:
{v:'VER',what:'the floor heading stays out of a station window: with the shop or Fashion open THE UNDERCROFT is not painted behind the window, where its top half showed above the frame, and with the window shut it is painted again',
 run:function(){
   if(typeof __station!=='function'||typeof __hubEnter!=='function'||typeof __hubStep!=='function') return 'SKIP: no Undercroft floor here';
   var bad=[], t, oFT=ctx.fillText, rec=[], hd='THE UNDER'+'CROFT', ids=['trader','mirror'], i, open;
   function drawn(){ var j; for(j=0;j<rec.length;j++) if(rec[j]===hd) return true; return false; }
   function shut(){ var a=document.querySelectorAll('.modal.on'), k; for(k=0;k<a.length;k++) a[k].classList.remove('on'); }
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     t=document.getElementById('title'); if(t) t.classList.remove('on');
     __hubEnter(); shut();
     ctx.fillText=function(s){ rec.push(String(s)); return oFT.apply(this,arguments); };
     rec=[]; __hubStep(0.016);
     if(!drawn()) return 'SKIP: the floor drew no heading with no window open';
     for(i=0;i<ids.length;i++){
       __station(ids[i],'KeyE');
       open=document.querySelector('.modal.on');
       if(!open){ bad.push('the '+ids[i]+' station opened no window'); continue; }
       rec=[]; __hubStep(0.016);
       if(drawn()) bad.push('the floor heading is painted behind the '+open.id+' window');
       shut();
     }
     rec=[]; __hubStep(0.016);
     if(!drawn()) bad.push('the floor heading did not come back when the window shut');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ delete ctx.fillText; if(ctx.fillText!==oFT) ctx.fillText=oFT; shut(); __topClear(); __cleanProfile(); }
   return bad.length?bad.join('; '):null; }},
